const views=['list','overview','summary','classification','review','states'];
function show(name,focusHeading=false){if(!views.includes(name))name='list';document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+name));document.querySelectorAll('.harness [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));history.replaceState(null,'','#'+name);if(focusHeading){const h=document.querySelector('#view-'+name+' h1');if(h){h.tabIndex=-1;h.focus()}}}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.view,true)));document.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();show(b.dataset.jump,true)}));document.addEventListener('keydown',e=>{const t=e.target;if(!t.matches('.tab[role="tab"]'))return;const tabs=[...document.querySelectorAll('.view.active .tab[role="tab"]')],i=tabs.indexOf(t);if(i<0)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const d=e.key==='ArrowRight'?1:-1;tabs[(i+d+tabs.length)%tabs.length].focus()}if(e.key==='Enter'||e.key===' '){e.preventDefault();t.click()}});document.getElementById('save-summary').addEventListener('click',()=>document.getElementById('summary-feedback').classList.remove('hidden'));document.getElementById('save-classification').addEventListener('click',()=>document.getElementById('classification-feedback').classList.remove('hidden'));document.getElementById('filter-toggle').addEventListener('click',e=>{const n=document.getElementById('filter-note'),open=n.classList.toggle('hidden')===false;e.currentTarget.setAttribute('aria-expanded',String(open))});show(location.hash.slice(1)||'list');
